//! `open_tabs`: the order tabs open in the workspace, with unsaved drafts.

use super::{col_order_kind, col_ts, ts_text};
use crate::conn::{Conn, Tx};
use crate::error::Result;
use crm_domain::{OrderId, OrderKind};
use jiff::Timestamp;
use rusqlite::params;

/// One open order tab.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OpenTab {
    /// Key generated by the UI.
    pub tab_key: String,
    /// Left-to-right position.
    pub position: i64,
    /// Shitje / Blerje.
    pub kind: OrderKind,
    /// The saved order shown, or `None` for a new one.
    pub order_id: Option<OrderId>,
    /// Tab title.
    pub title: String,
    /// Whether this is the selected tab.
    pub active: bool,
    /// The unsaved draft as JSON (`None` = no unsaved changes).
    pub draft_json: Option<String>,
    /// Last change.
    pub updated_at: Timestamp,
}

/// Every open tab, by position.
pub fn list(c: &Conn<'_>) -> Result<Vec<OpenTab>> {
    let mut stmt = c.raw().prepare(
        "SELECT tab_key, position, kind, order_id, title, active, draft_json, updated_at
         FROM open_tabs ORDER BY position, tab_key",
    )?;
    let tabs = stmt
        .query_map([], |r| {
            Ok(OpenTab {
                tab_key: r.get(0)?,
                position: r.get(1)?,
                kind: col_order_kind(r, 2)?,
                order_id: r.get::<_, Option<i64>>(3)?.map(OrderId),
                title: r.get(4)?,
                active: r.get::<_, i64>(5)? != 0,
                draft_json: r.get(6)?,
                updated_at: col_ts(r, 7)?,
            })
        })?
        .collect::<rusqlite::Result<_>>()?;
    Ok(tabs)
}

/// Inserts the tab, or overwrites the one with the same key.
pub fn upsert(tx: &Tx<'_>, tab: &OpenTab) -> Result<()> {
    tx.raw().execute(
        "INSERT INTO open_tabs (tab_key, position, kind, order_id, title, active, draft_json,
                                updated_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
         ON CONFLICT (tab_key) DO UPDATE SET
             position = excluded.position, kind = excluded.kind, order_id = excluded.order_id,
             title = excluded.title, active = excluded.active, draft_json = excluded.draft_json,
             updated_at = excluded.updated_at",
        params![
            tab.tab_key,
            tab.position,
            tab.kind.as_i64(),
            tab.order_id.map(|o| o.0),
            tab.title,
            i64::from(tab.active),
            tab.draft_json,
            ts_text(tab.updated_at)
        ],
    )?;
    Ok(())
}

/// Closes one tab. Returns whether it existed.
pub fn remove(tx: &Tx<'_>, tab_key: &str) -> Result<bool> {
    Ok(tx
        .raw()
        .execute("DELETE FROM open_tabs WHERE tab_key = ?1", [tab_key])?
        > 0)
}

/// Closes every tab.
pub fn clear_all(tx: &Tx<'_>) -> Result<()> {
    tx.raw().execute("DELETE FROM open_tabs", [])?;
    Ok(())
}

/// Marks `tab_key` as the only active tab.
pub fn set_active(tx: &Tx<'_>, tab_key: &str) -> Result<()> {
    tx.raw()
        .execute("UPDATE open_tabs SET active = (tab_key = ?1)", [tab_key])?;
    Ok(())
}
